mapper.select:
SELECT
    COUNT(*) AS total,
    SUM(CASE WHEN po.state = 2 THEN 1 ELSE 0 END) AS success,
    COALESCE(SUM(CASE WHEN po.state = 2 THEN po.amount ELSE 0 END), 0) AS total_amount,
    (SELECT COUNT(*) FROM t_refund_order ro
      INNER JOIN t_pay_order po2 ON po2.pay_order_id = ro.pay_order_id
      WHERE po2.mch_no = #{mchNo}
        AND ro.created_at >= #{startTime}
        AND ro.created_at < #{endTime}
        AND ro.state = 2) AS refund_count
FROM t_pay_order po
WHERE po.mch_no = #{mchNo}
  AND po.created_at >= #{startTime}
  AND po.created_at < #{endTime}
  AND po.state IN (2, 3)

SELECT COUNT(*) FROM t_chargeback_record
WHERE mch_no = #{mchNo}
  AND created_at >= #{startTime}
  AND created_at < #{endTime}
